package local.mediacenter.library
import android.content.Context
import android.net.Uri
import android.util.AtomicFile
import java.io.File
import java.util.UUID
import org.json.*

/** Native-only encrypted migration. Restore never merges into an existing media installation. */
internal object NativeBackup {
 fun safeMessage(e:Exception):String {val m=e.message.orEmpty();if(m in setOf("Stop playback before applying a progress choice","Close the video player before reviewing progress"))return "Stop audio and close video before using migration backups";return if(m in setOf("Wait for pending server progress reports to finish, then refresh the preview.","Password is incorrect or the backup is damaged. Nothing was restored.","Restore on a fresh installation before adding connections","Stop audio and close video before using migration backups","Pause transfers and wait for verification before using migration backups","Stop the podcast inbox check before using migration backups","Backup preview expired. Choose the file again.","Choose the backup again","Use a backup password with 12–1,024 characters","Backup exceeds 64 MiB","Backup exceeds the 64 MiB archive limit","Restore before creating cache transfers","Restore before adding local media","Restore before adding custom covers, lyrics or transcripts","Restore before creating listening history or podcast inbox entries","Restore before creating personal library content"))m else "Could not use this migration backup. Check its format, password, storage and folder access. No unconfirmed restore was applied."}
 private data class Prepared(val token:String,val contents:BackupContents,val expires:Long)
 private var prepared:Prepared?=null
 private val expiry=java.util.concurrent.Executors.newSingleThreadScheduledExecutor{r->Thread(r,"backup-preview-expiry").apply{isDaemon=true}}
 private var expiryTask:java.util.concurrent.ScheduledFuture<*>?=null
 @Volatile var restoring=false;private set
 @Volatile var recoveryError="";private set
 fun recoverOnLaunch(c:Context){try{recover(c);recoveryError=""}catch(_:Exception){recoveryError="Migration recovery could not finish. Stop playback and retry recovery in Settings. The recovery journal was kept."}}
 fun retryRecovery(c:Context)=exclusive(c){recover(c);recoveryError="";true}
 private fun preferences(c:Context,name:String)=c.getSharedPreferences(name,Context.MODE_PRIVATE)
 private fun journal(c:Context)=AtomicFile(File(c.filesDir,"migration-rollback.json"))
 private fun prefSnapshot(c:Context,portable:Boolean):JSONObject {val out=JSONObject();for(name in BackupData.preferences){val data=JSONObject();for((key,value)in preferences(c,name).all){if(portable&&key.startsWith("account."))continue;if(portable&&name=="media_downloads"&&key !in setOf("policy","template"))continue;if(portable&&name=="device_library"&&key!="stations")continue;require(value is String){"Unsupported preference value in backup"};data.put(key,value)};out.put(name,data)};return out}
 private fun putPrefs(c:Context,data:JSONObject){for(name in BackupData.preferences){val rows=data.getJSONObject(name);val edit=preferences(c,name).edit().clear();for(k in rows.keys())edit.putString(k,rows.getString(k));check(edit.commit()){"Could not save restored settings"}}}
 private fun writeJournal(c:Context,value:JSONObject){val file=journal(c);val out=file.startWrite();try{out.write(value.toString().toByteArray(Charsets.UTF_8));file.finishWrite(out)}catch(e:Exception){file.failWrite(out);throw e}}
 private fun target(c:Context,path:String):File {require(BackupArchive.asset(path));val file=File(c.filesDir,path);require(file.canonicalPath.startsWith(c.filesDir.canonicalPath+File.separator));return file}
 private fun files(c:Context):Map<String,ByteArray>{val result=linkedMapOf<String,ByteArray>();var total=0L;for(folder in BackupArchive.folders)for(f in File(c.filesDir,folder).listFiles().orEmpty()){val relative="$folder/${f.name}";if(!f.isFile||!BackupArchive.asset(relative))continue;require(f.canonicalPath==target(c,relative).canonicalPath&&f.length()<=16*1024*1024){"A custom asset cannot be backed up"};total+=f.length();require(total<=BackupArchive.EXPANDED){"Custom assets exceed the backup limit"};result[relative]=f.readBytes()};return result}
 private fun validateAssets(contents:BackupContents){for((path,bytes)in contents.assets){when{path.endsWith(".image")-> {val options=android.graphics.BitmapFactory.Options().apply{inJustDecodeBounds=true};android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.size,options);require(options.outWidth in 1..4096&&options.outHeight in 1..4096){"Backup image dimensions are unsupported"}}
 path.startsWith("spoken-transcripts/")->NativeTranscripts.text(bytes)
 path.startsWith("mix-snapshots/")->JSONObject(String(bytes,Charsets.UTF_8))
 }}}
 private fun restoredAsset(path:String,bytes:ByteArray,root:JSONObject):ByteArray {
  if(!path.startsWith("mix-snapshots/"))return bytes
  val ui=JSONObject(root.getJSONObject("preferences").getJSONObject("media_library").optString("ui","{}"));val recipes=ui.optJSONArray("mixRecipes")?:return bytes
  for(i in 0 until recipes.length()){val d=MixSnapshotPlan.definition(recipes.getJSONObject(i));if(path!="mix-snapshots/"+BackupArchive.digest(d.id.toByteArray(Charsets.UTF_8))+".json")continue
   val saved=JSONObject(String(bytes,Charsets.UTF_8));saved.optJSONArray("rows")?.let{saved.put("rows",MixSnapshotPlan.rows(it,d)).put("fingerprint",d.fingerprint).put("period",0);saved.remove("attemptFingerprint");saved.remove("retryAfter")};return saved.toString().toByteArray(Charsets.UTF_8)
  };return bytes
 }
 private fun idle(c:Context){require(!VideoActivity.hasOpenVideo()){ "Stop audio and close video before using migration backups" };require(!PodcastInbox.snapshot(c,JSONObject(),true).getBoolean("busy")){"Stop the podcast inbox check before using migration backups"}}
 private fun fresh(c:Context){require(preferences(c,"media_library").all.keys.none{it.startsWith("account.")}){"Restore on a fresh installation before adding connections"};require(preferences(c,"media_downloads").getString("items","[]")=="[]"&&preferences(c,"media_downloads").getString("jobs","[]")=="[]"){"Restore before creating cache transfers"};val local=DeviceLibrary.list(c);require(local.getJSONArray("files").length()==0&&local.getJSONArray("stations").length()==0){"Restore before adding local media"};require(files(c).isEmpty()&&preferences(c,"custom_lyrics").all.isEmpty()&&preferences(c,"custom_covers").all.isEmpty()){ "Restore before adding custom covers, lyrics or transcripts" };val tables=BackupTables.snapshot(c);require(BackupData.tables.all{tables.getJSONArray(it.name).length()==0}){"Restore before creating listening history or podcast inbox entries"};val ui=JSONObject(preferences(c,"media_library").getString("ui","{}")?:"{}");for(k in listOf("pins","personalPlaylists","mixRecipes","bookmarks","collections"))require((ui.optJSONArray(k)?.length()?:0)==0){"Restore before creating personal library content"}}
 private fun <T> exclusive(c:Context,block:()->T):T=OfflineStore.maintenance{Playback.idleProgressEdit{synchronized(this){idle(c);block()}}}
 fun export(c:Context,uri:Uri,password:CharArray){exclusive(c){require(recoveryError.isEmpty()){recoveryError};require(uri.scheme=="content");val sources=JSONArray();val prefs=preferences(c,"media_library");for(k in prefs.all.keys.filter{it.startsWith("account.")})sources.put(EncryptedAccounts.read(c,k.removePrefix("account.")));val root=JSONObject().put("formatVersion",1).put("created",System.currentTimeMillis()).put("accounts",sources).put("preferences",prefSnapshot(c,true)).put("tables",BackupTables.snapshot(c));val archive=BackupArchive.pack(root,files(c));try{val encrypted=BackupCipher.encrypt(archive,password);try{requireNotNull(c.contentResolver.openOutputStream(uri,"wt")).use{it.write(encrypted)}}finally{encrypted.fill(0)}}finally{archive.fill(0)}}}
 fun preview(c:Context,uri:Uri,password:CharArray):String=exclusive(c){require(recoveryError.isEmpty()){recoveryError};require(uri.scheme=="content");discard();val encrypted=requireNotNull(c.contentResolver.openInputStream(uri)).use{input->val out=java.io.ByteArrayOutputStream();val block=ByteArray(16384);while(true){val n=input.read(block);if(n<0)break;require(out.size()+n<=BackupCipher.LIMIT){"Backup exceeds 64 MiB"};out.write(block,0,n)};out.toByteArray()};val archive=try{BackupCipher.decrypt(encrypted,password)}finally{encrypted.fill(0)};val contents=try{BackupArchive.unpack(archive)}finally{archive.fill(0)};validateAssets(contents);val checked=BackupData.safeRestore(contents.manifest);BackupData.validate(checked);for((path,bytes)in contents.assets){val validated=restoredAsset(path,bytes,checked);if(validated!==bytes)validated.fill(0)};val summary=BackupData.summary(contents.manifest).put("verified",true);if(runCatching{fresh(c)}.isFailure){contents.assets.values.forEach{it.fill(0)};return@exclusive summary.put("canRestore",false).toString()};val token=UUID.randomUUID().toString();prepared=Prepared(token,contents,android.os.SystemClock.elapsedRealtime()+5*60000);expiryTask=expiry.schedule({synchronized(this){if(prepared?.token==token)discard()}},5,java.util.concurrent.TimeUnit.MINUTES);summary.put("canRestore",true).put("token",token).toString()}
 fun releasePreviewAsync(){expiry.execute{discard()}}
 @Synchronized fun discard(){expiryTask?.cancel(false);expiryTask=null;prepared?.contents?.assets?.values?.forEach{it.fill(0)};prepared=null}
 fun apply(c:Context,token:String):String=exclusive(c){val p=requireNotNull(prepared){"Choose the backup again"};if(p.token!=token||android.os.SystemClock.elapsedRealtime()>p.expires){discard();throw IllegalArgumentException("Backup preview expired. Choose the file again.")};require(recoveryError.isEmpty()){recoveryError};fresh(c);val root=BackupData.safeRestore(p.contents.manifest);val baseline=JSONObject().put("preferences",prefSnapshot(c,false)).put("paths",JSONArray(p.contents.assets.keys)).put("committed",false);restoring=true
  try{writeJournal(c,baseline);BackupTables.replace(c,root.getJSONObject("tables"));for((path,bytes)in p.contents.assets){val f=target(c,path);check(f.parentFile!!.isDirectory||f.parentFile!!.mkdirs());val atomic=AtomicFile(f);val out=atomic.startWrite();try{out.write(restoredAsset(path,bytes,root));atomic.finishWrite(out)}catch(e:Exception){atomic.failWrite(out);throw e}};putPrefs(c,root.getJSONObject("preferences"));val sources=root.getJSONArray("accounts");for(i in 0 until sources.length()){val a=sources.getJSONObject(i);EncryptedAccounts.write(c,a.getString("id"),a)};writeJournal(c,baseline.put("committed",true));discard();"Restored. Folder permissions and downloaded media must be selected separately. Automatic rules are off."
  }catch(e:Exception){recoverOnLaunch(c);restoring=false;throw e}
 }
 @Synchronized fun finish(c:Context){if(restoring){journal(c).delete();restoring=false;OfflineRulesScheduler.configure(c);RetainedArtwork.refresh(c)}}
 /** A killed import either rolls back its fresh destination or keeps its committed result. */
 @Synchronized fun recover(c:Context){val file=journal(c);val raw=try{file.openRead().bufferedReader(Charsets.UTF_8).use{it.readText()}}catch(_:java.io.FileNotFoundException){return};require(raw.length<=16*1024*1024);val j=JSONObject(raw);if(!j.getBoolean("committed")){putPrefs(c,j.getJSONObject("preferences"));BackupTables.replace(c,BackupTables.empty());val paths=j.getJSONArray("paths");for(i in 0 until paths.length()){val target=target(c,paths.getString(i));AtomicFile(target).delete();check(!target.exists()&&!File(target.path+".bak").exists()&&!File(target.path+".new").exists()){"Could not remove staged migration data"}}};file.delete();restoring=false}
}
